#!/usr/bin/env python3
"""Save every design generated by the Wang et al. R800 cantilever.

This is a visualization run, not a performance benchmark. Device-to-host
transfers and roughly 24 GiB of density output are intentionally included.
"""

from __future__ import annotations

import argparse
import csv
import os
from pathlib import Path
import time

import jax
import jax.numpy as jnp
import numpy as np

import topax


jax.config.update("jax_enable_x64", True)


ELEMENTS = np.array((800, 400, 400), dtype=int)
SIZES = np.array((1.0, 0.5, 0.5), dtype=np.float64)
N_LEVELS = 4
GALERKIN_CROSSOVER_LEVEL = 2
N_SMOOTHING_STEPS = 1
SLAB_SIZE = topax.operator.DEFAULT_SLAB_SIZE
GALERKIN_SLAB_SIZE = topax.galerkin.DEFAULT_GALERKIN_SLAB_SIZE

ELASTIC_MODULUS = 1.0
POISSON_RATIO = 0.3
RHO_MIN = 1.0e-6
SIMP_PENALTY = 3.0
VOLUME_FRACTION = 0.12
N_DESIGN_ITERATIONS = 50

OC_MOVE = 0.2
OC_BISECTION_TOL = 1.0e-6
OC_STEP = topax.optimizer.oc.construct_oc_step(
    topax.optimizer.oc.init_oc_params(
        move=OC_MOVE,
        bisect_tol=OC_BISECTION_TOL,
    )
)

PHYSICS_TOLERANCE = 1.0e-3
FILTER_TOLERANCE = 1.0e-4
CG_MAX_ITERATIONS = 600
JACOBI_DAMPING = 0.5

# Figure 10b uses sqrt(3) elements at R48 and scales the radius with the
# resolution. The R800 multiplier is 17. TOP3D_XL's released element matrix
# is equivalent to Topax's conventional Helmholtz matrix at sqrt(2) times the
# nominal physical radius.
FILTER_RADIUS_ELEMENTS = float(17.0 * np.sqrt(3.0))
FILTER_RADIUS_PHYSICAL = float(FILTER_RADIUS_ELEMENTS / ELEMENTS[0])
TOPAX_HELMHOLTZ_RADIUS = float(np.sqrt(2.0) * FILTER_RADIUS_PHYSICAL)

FIXED_FACE = {
    "center": [0.0, 0.5, 0.5],
    "size": [0.0, 1.0, 1.0],
}
DIRICHLET_BOUNDARY_CONDITIONS = (
    (FIXED_FACE,),
    (FIXED_FACE,),
    (FIXED_FACE,),
)

ITERATION_FIELDS = (
    "iteration",
    "evaluated_density_file",
    "updated_density_file",
    "compliance",
    "mean_design_density",
    "volume_constraint",
    "non_discreteness",
    "change",
    "physics_cg_iterations",
    "physics_relative_residual",
    "filter_cg_iterations",
    "filter_relative_residual",
    "solve_time_s",
    "save_time_s",
)


def prepare_output_directory(path: Path) -> tuple[Path, Path]:
    path = path.expanduser().resolve()
    path.mkdir(parents=True, exist_ok=False)
    density_directory = path / "density"
    density_directory.mkdir()
    return path, density_directory


def density_filename(iteration: int) -> str:
    return f"density/iteration_{iteration:03d}.npy"


def save_density(directory: Path, iteration: int, rho) -> Path:
    destination = directory / f"iteration_{iteration:03d}.npy"
    temporary = directory / f".iteration_{iteration:03d}.{os.getpid()}.npy"
    if destination.exists():
        raise FileExistsError(f"density frame already exists: {destination}")

    host_density = np.asarray(
        jax.device_get(jnp.asarray(rho, dtype=jnp.float32))
    )
    with temporary.open("wb") as stream:
        np.save(stream, host_density, allow_pickle=False)
    temporary.replace(destination)
    return destination


def write_configuration(path: Path, device, max_iterations: int) -> None:
    n_elements = int(np.prod(ELEMENTS))
    n_nodes = int(np.prod(ELEMENTS + 1))
    contents = f'''schema_version = 1
problem = "Wang et al. 2025 R800 cantilever"
purpose = "visualization"
elements = [{ELEMENTS[0]}, {ELEMENTS[1]}, {ELEMENTS[2]}]
n_elements = {n_elements}
n_displacement_dofs = {3 * n_nodes}
domain_size = [{SIZES[0]}, {SIZES[1]}, {SIZES[2]}]
design_iterations = {max_iterations}
saved_frames = {max_iterations + 1}
density_dtype = "float32"
density_axis_order = "x,y,z"
device = "{device}"

[material]
youngs_modulus = {ELASTIC_MODULUS}
poisson_ratio = {POISSON_RATIO}
minimum_relative_stiffness = {RHO_MIN}
simp_penalty = {SIMP_PENALTY}
volume_fraction = {VOLUME_FRACTION}

[filter]
kind = "TOP3D_XL PDE sensitivity filter"
series = "fixed physical radius"
filter_radius_elements = {FILTER_RADIUS_ELEMENTS}
filter_radius_physical = {FILTER_RADIUS_PHYSICAL}
equivalent_topax_helmholtz_radius = {TOPAX_HELMHOLTZ_RADIUS}
tolerance = {FILTER_TOLERANCE}

[multigrid]
levels = {N_LEVELS}
galerkin_crossover_level = {GALERKIN_CROSSOVER_LEVEL}
smoothing_steps = {N_SMOOTHING_STEPS}
jacobi_damping = {JACOBI_DAMPING}
fine_grid_slab_size = {SLAB_SIZE}
galerkin_slab_size = {GALERKIN_SLAB_SIZE}
physics_tolerance = {PHYSICS_TOLERANCE}
physics_max_iterations = {CG_MAX_ITERATIONS}

[optimization]
method = "optimality criteria"
move_limit = {OC_MOVE}
'''
    path.write_text(contents)


def construct_forces(grid):
    nelx, nely, nelz = map(int, grid.elements)
    n_loaded_z_nodes = int(np.round(nelz / 6.0 + 1.0))
    n_loaded_nodes = (nely + 1) * n_loaded_z_nodes
    forces = jnp.zeros((3, nelx + 1, nely + 1, nelz + 1), dtype=jnp.float64)
    return forces.at[2, -1, :, :n_loaded_z_nodes].set(-1.0 / n_loaded_nodes)


def construct_problem():
    elastic = topax.construct_elastic(ELASTIC_MODULUS, POISSON_RATIO)
    grid = topax.construct_grid(N_LEVELS, SIZES, ELEMENTS)
    fine_local_stiffness = topax.construct_local_stiffness(
        grid.fine_level,
        elastic,
    )
    restrictions = topax.construct_restrictions(
        grid,
        elastic,
        DIRICHLET_BOUNDARY_CONDITIONS,
    )
    forces = construct_forces(grid)
    coarse_physics_structure = topax.sparse.construct_sparse_physics_structure(
        grid.coarse_level,
        n_dofs_node=grid.n_dims,
        restriction=restrictions[-1],
    )

    helmholtz = topax.construct_helmholtz(
        filter_radius=TOPAX_HELMHOLTZ_RADIUS,
        thickness=1.0,
    )
    local_helmholtz_operators = tuple(
        topax.construct_local_helmholtz(level, helmholtz)
        for level in grid.levels
    )
    coarse_helmholtz_structure = topax.sparse.construct_sparse_helmholtz_structure(
        grid.coarse_level,
        local_helmholtz_operators[-1],
    )
    return (
        grid,
        fine_local_stiffness,
        restrictions,
        forces,
        coarse_physics_structure,
        helmholtz,
        local_helmholtz_operators,
        coarse_helmholtz_structure,
    )


def measure_non_discreteness(rho):
    return jnp.mean(4.0 * rho * (1.0 - rho))


def construct_optimization_step(
    *,
    grid,
    fine_local_stiffness,
    coarse_physics_structure,
    helmholtz,
    local_helmholtz_operators,
    coarse_helmholtz_structure,
):
    fine_level = grid.fine_level

    def optimization_step(
        solvers,
        rho,
        forces,
        rho_mask,
        restrictions,
        physics_value0,
        filter_value0,
    ):
        physics_solver, displacement, physics_info = (
            topax.vcycle.physics_vcycle_solve(
                solver=solvers.physics,
                grid=grid,
                fine_local_operator=fine_local_stiffness,
                coarse_structure=coarse_physics_structure,
                rho=rho,
                forces=forces,
                restrictions=restrictions,
                x0=physics_value0,
                simp_penalty=SIMP_PENALTY,
                rho_min=RHO_MIN,
                damping=JACOBI_DAMPING,
                tol=PHYSICS_TOLERANCE,
                maxiter=CG_MAX_ITERATIONS,
                n_smoothing_steps=N_SMOOTHING_STEPS,
                galerkin_crossover_level=GALERKIN_CROSSOVER_LEVEL,
                galerkin_slab_size=GALERKIN_SLAB_SIZE,
                slab_size=SLAB_SIZE,
            )
        )
        displacement = jax.lax.stop_gradient(displacement)

        compliance = jnp.vdot(forces, displacement).real
        strain_energy = topax.operator.element_strain_energy(
            fine_level,
            displacement,
            fine_local_stiffness,
            restrictions[0],
            slab_size=SLAB_SIZE,
        )
        positive_stiffness_gradient = (
            SIMP_PENALTY
            * (1.0 - RHO_MIN)
            * rho ** (SIMP_PENALTY - 1.0)
            * strain_energy
        )
        sensitivity_source = -rho * positive_stiffness_gradient
        filter_rhs = topax.helmholtz_to_nodal(
            fine_level,
            helmholtz,
            sensitivity_source,
        )
        helmholtz_solver, filtered_nodal, filter_info = (
            topax.vcycle.helmholtz_vcycle_solve(
                solver=solvers.helmholtz,
                grid=grid,
                local_operators=local_helmholtz_operators,
                coarse_structure=coarse_helmholtz_structure,
                rho_mask=rho_mask,
                rho_nodal=filter_rhs,
                x0=filter_value0,
                damping=JACOBI_DAMPING,
                tol=FILTER_TOLERANCE,
                maxiter=CG_MAX_ITERATIONS,
                n_smoothing_steps=N_SMOOTHING_STEPS,
                slab_size=SLAB_SIZE,
            )
        )
        filtered_sensitivity = topax.helmholtz_to_elemental(
            fine_level,
            filtered_nodal,
        )
        objective_gradient = filtered_sensitivity / jnp.maximum(1.0e-3, rho)

        volume_constraint = jnp.mean(rho) - VOLUME_FRACTION
        rho_new, oc_info = OC_STEP(
            rho,
            objective_gradient,
            volume_constraint,
            jnp.ones_like(rho),
        )

        force_norm = jnp.linalg.norm(forces)
        filter_rhs_norm = jnp.linalg.norm(filter_rhs)
        tiny = jnp.finfo(rho.dtype).tiny
        physics_relative_residual = jnp.sqrt(
            physics_info["error"]
        ) / jnp.maximum(force_norm, tiny)
        filter_relative_residual = jnp.sqrt(filter_info["error"]) / jnp.maximum(
            filter_rhs_norm,
            tiny,
        )
        diagnostics = (
            compliance,
            jnp.mean(rho),
            volume_constraint,
            measure_non_discreteness(rho),
            oc_info["change"],
            physics_info["n_iter"],
            physics_info["converged"],
            physics_relative_residual,
            filter_info["n_iter"],
            filter_info["converged"],
            filter_relative_residual,
        )
        return (
            solvers._replace(
                physics=physics_solver,
                helmholtz=helmholtz_solver,
            ),
            rho_new,
            displacement,
            filtered_nodal,
            diagnostics,
        )

    return jax.jit(optimization_step, donate_argnums=(1, 5, 6))


def run(output_directory: Path, max_iterations: int) -> None:
    output_directory, density_directory = prepare_output_directory(
        output_directory
    )
    device = jax.devices()[0]
    write_configuration(
        output_directory / "configuration.toml",
        device,
        max_iterations,
    )
    print(f"output:             {output_directory}")
    print(f"device:             {device}")
    print("constructing R800 L4-C2 problem")

    (
        grid,
        fine_local_stiffness,
        restrictions,
        forces,
        coarse_physics_structure,
        helmholtz,
        local_helmholtz_operators,
        coarse_helmholtz_structure,
    ) = construct_problem()

    rho = jnp.full(tuple(map(int, ELEMENTS)), VOLUME_FRACTION, dtype=jnp.float64)
    rho_mask = jnp.ones_like(rho, dtype=jnp.bool_)
    physics_value0 = jnp.zeros(
        (3, *map(int, grid.fine_level.nodes)),
        dtype=jnp.float64,
    )
    filter_value0 = jnp.zeros(
        (1, *map(int, grid.fine_level.nodes)),
        dtype=jnp.float64,
    )
    solvers = topax.solver.setup_cg_filter_solver_state(
        coarse_physics_structure,
        coarse_helmholtz_structure,
        grid,
        restrictions,
    )
    optimization_step = construct_optimization_step(
        grid=grid,
        fine_local_stiffness=fine_local_stiffness,
        coarse_physics_structure=coarse_physics_structure,
        helmholtz=helmholtz,
        local_helmholtz_operators=local_helmholtz_operators,
        coarse_helmholtz_structure=coarse_helmholtz_structure,
    )

    print("compiling optimization step")
    compiled_step = optimization_step.lower(
        solvers,
        rho,
        forces,
        rho_mask,
        restrictions,
        physics_value0,
        filter_value0,
    ).compile()

    print("running untimed warm-up")
    warmup_outputs = compiled_step(
        solvers,
        jnp.array(rho, copy=True),
        forces,
        rho_mask,
        restrictions,
        jnp.array(physics_value0, copy=True),
        jnp.array(filter_value0, copy=True),
    )
    jax.block_until_ready(warmup_outputs)
    solvers = warmup_outputs[0]
    if not bool(warmup_outputs[-1][6]):
        topax.solver.close_solver_state(solvers)
        raise RuntimeError("Physics CG did not converge during warm-up.")
    if not bool(warmup_outputs[-1][9]):
        topax.solver.close_solver_state(solvers)
        raise RuntimeError("Sensitivity-filter CG did not converge during warm-up.")
    del warmup_outputs

    save_start = time.perf_counter()
    save_density(density_directory, 0, rho)
    print(f"saved iteration 000 in {time.perf_counter() - save_start:.3f} s")

    history_path = output_directory / "iterations.csv"
    completed_iterations = 0
    try:
        with history_path.open("w", newline="") as history_stream:
            writer = csv.DictWriter(history_stream, fieldnames=ITERATION_FIELDS)
            writer.writeheader()
            history_stream.flush()

            for iteration in range(1, max_iterations + 1):
                solve_start = time.perf_counter()
                (
                    solvers,
                    rho,
                    physics_value0,
                    filter_value0,
                    diagnostics,
                ) = compiled_step(
                    solvers,
                    rho,
                    forces,
                    rho_mask,
                    restrictions,
                    physics_value0,
                    filter_value0,
                )
                jax.block_until_ready(
                    (solvers, rho, physics_value0, filter_value0, diagnostics)
                )
                solve_time = time.perf_counter() - solve_start

                (
                    compliance,
                    mean_density,
                    volume_constraint,
                    non_discreteness,
                    change,
                    physics_n_iter,
                    physics_converged,
                    physics_relative_residual,
                    filter_n_iter,
                    filter_converged,
                    filter_relative_residual,
                ) = diagnostics
                if not bool(physics_converged):
                    raise RuntimeError(
                        f"Physics CG did not converge at iteration {iteration}."
                    )
                if not bool(filter_converged):
                    raise RuntimeError(
                        "Sensitivity-filter CG did not converge at iteration "
                        f"{iteration}."
                    )

                save_start = time.perf_counter()
                save_density(density_directory, iteration, rho)
                save_time = time.perf_counter() - save_start
                row = {
                    "iteration": iteration,
                    "evaluated_density_file": density_filename(iteration - 1),
                    "updated_density_file": density_filename(iteration),
                    "compliance": float(compliance),
                    "mean_design_density": float(mean_density),
                    "volume_constraint": float(volume_constraint),
                    "non_discreteness": float(non_discreteness),
                    "change": float(change),
                    "physics_cg_iterations": int(physics_n_iter),
                    "physics_relative_residual": float(
                        physics_relative_residual
                    ),
                    "filter_cg_iterations": int(filter_n_iter),
                    "filter_relative_residual": float(filter_relative_residual),
                    "solve_time_s": solve_time,
                    "save_time_s": save_time,
                }
                writer.writerow(row)
                history_stream.flush()
                completed_iterations = iteration
                print(
                    f"iter {iteration:3d} | c {float(compliance):12.6e} | "
                    f"rho {float(mean_density):.6f} | "
                    f"MDN {float(non_discreteness):.6f} | "
                    f"change {float(change):.3e} | "
                    f"CG(K) {int(physics_n_iter):4d} | "
                    f"CG(H) {int(filter_n_iter):4d} | "
                    f"solve {solve_time:.3f} s | save {save_time:.3f} s"
                )
    finally:
        topax.solver.close_solver_state(solvers)

    if completed_iterations == max_iterations:
        (output_directory / "COMPLETE").write_text(
            f"completed_iterations = {completed_iterations}\n"
        )
    print(f"completed {completed_iterations} design iterations")
    print(f"density history:    {density_directory}")


def parse_args(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output-dir",
        type=Path,
        required=True,
        help="exact output directory for this run (must not already exist)",
    )
    parser.add_argument(
        "--max-iterations",
        type=int,
        default=N_DESIGN_ITERATIONS,
        help=f"number of saved design updates (default: {N_DESIGN_ITERATIONS})",
    )
    args = parser.parse_args(argv)
    if not 1 <= args.max_iterations <= N_DESIGN_ITERATIONS:
        parser.error(
            f"--max-iterations must be between 1 and {N_DESIGN_ITERATIONS}"
        )
    return args


def main():
    args = parse_args()
    run(args.output_dir, args.max_iterations)


if __name__ == "__main__":
    main()

